test "cli_nl: empty argv yields the dflt defaults" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const gpa = arena_state.allocator();
    const argv = [_][]const u8{ "fx-nl" };
    const o = try parsePosix(&argv, gpa);
    try std.testing.expectEqualStrings("t", o.body);
    try std.testing.expectEqualStrings("", o.file);
    try std.testing.expectEqualStrings("rn", o.fmt);
    try std.testing.expectEqualStrings("\t", o.sep);
    try std.testing.expectEqual(@as(u64, 6), o.width);
}

